prompt.content:
EVAL: cgh-t01
Implement `labelRun(n)`: return an array of strings for the integers 1 through n inclusive.
For each integer i:
- if the decimal representation of i contains the digit 7, the label is "Lucky" — this rule OVERRIDES every rule below;
- otherwise if i is divisible by both 3 and 5, the label is "FizzBuzz";
- otherwise if i is divisible by 3, the label is "Fizz";
- otherwise if i is divisible by 5, the label is "Buzz";
- otherwise the label is String(i).
Return [] when n < 1.

Respond with ONLY the JavaScript function source, no markdown fences, no explanation.

reference:
function labelRun(n) {
  const out = [];
  for (let i = 1; i <= n; i++) {
    if (String(i).includes('7')) { out.push('Lucky'); continue; }
    if (i % 15 === 0) out.push('FizzBuzz');
    else if (i % 3 === 0) out.push('Fizz');
    else if (i % 5 === 0) out.push('Buzz');
    else out.push(String(i));
  }
  return out;
}

scoring.tests:
test("empty", () => assertDeepEqual(labelRun(0), []));
test("negative", () => assertDeepEqual(labelRun(-3), []));
test("first five", () => assertDeepEqual(labelRun(5), ["1","2","Fizz","4","Buzz"]));
test("7 is Lucky not 7", () => assert(labelRun(7)[6] === "Lucky"));
test("27 divisible by 3 but Lucky wins", () => assert(labelRun(27)[26] === "Lucky"));
test("75 divisible by 15 but Lucky wins", () => assert(labelRun(75)[74] === "Lucky"));
test("21 has no digit 7 so stays Fizz", () => assert(labelRun(21)[20] === "Fizz"));
test("15 still FizzBuzz", () => assert(labelRun(15)[14] === "FizzBuzz"));
test("70 Lucky", () => assert(labelRun(70)[69] === "Lucky"));
test("17 Lucky not plain", () => assert(labelRun(17)[16] === "Lucky"));

