function longestCircularRun(nums) {
  const n = nums.length;
  if (n === 0) return 0;
  let best = 1, cur = 1;
  for (let i = 1; i < 2 * n; i++) {
    if (nums[i % n] > nums[(i - 1) % n]) cur++; else cur = 1;
    if (cur > best) best = cur;
    if (best >= n) return n;
  }
  return Math.min(best, n);
}

