function allPairSums(nums, target) {
  const out = [];
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums.length; j++) {
      if (nums[i] + nums[j] === target) out.push([i, j]);
    }
  }
  return out;
}

