function reverseWordsKeepGaps(s) {
  const tokens = s.match(/ +|[^ ]+/g);
  if (!tokens) return '';
  const words = tokens.filter((t) => t[0] !== ' ');
  let k = words.length - 1;
  return tokens.map((t) => (t[0] === ' ' ? t : words[k--])).join('');
}

