function limitedCoinCombos(coins, amount) {
  let dp = new Array(amount + 1).fill(0);
  dp[0] = 1;
  for (const c of coins) {
    const next = new Array(amount + 1).fill(0);
    for (let a = 0; a <= amount; a++) {
      if (dp[a] === 0) continue;
      for (let k = 0; k <= 2; k++) {
        const t = a + k * c;
        if (t > amount) break;
        next[t] += dp[a];
      }
    }
    dp = next;
  }
  return dp[amount];
}

