function mergeSpans(spans) {
  const s = spans.slice().sort((a, b) => (a[0] - b[0]) || (a[1] - b[1]));
  const out = [];
  for (const cur of s) {
    const last = out[out.length - 1];
    if (last && cur[0] < last[1]) last[1] = Math.max(last[1], cur[1]);
    else out.push([cur[0], cur[1]]);
  }
  return out;
}

