function compressRuns(s) {
  if (s.includes('[') || s.includes(']')) return null;
  let out = '';
  let i = 0;
  while (i < s.length) {
    let j = i;
    while (j < s.length && s[j] === s[i]) j++;
    const n = j - i;
    out += n >= 4 ? s[i] + '[' + n + ']' : s[i].repeat(n);
    i = j;
  }
  return out;
}

