function balancedOutsideQuotes(s) {
  const pairs = { ')': '(', ']': '[', '}': '{' };
  const opens = { '(': 1, '[': 1, '{': 1 };
  const st = [];
  let inQ = false;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c === '\\') { i++; continue; }
    if (c === '"') { inQ = !inQ; continue; }
    if (inQ) continue;
    if (opens[c]) st.push(c);
    else if (pairs[c]) { if (st.pop() !== pairs[c]) return false; }
  }
  if (inQ) return false;
  return st.length === 0;
}

scoring.tests:
