function trailingAverages(nums, k) {
  if (!(k >= 1)) return null;
  const out = [];
  for (let i = 0; i < nums.length; i++) {
    const start = Math.max(0, i - k + 1);
    let sum = 0;
    for (let j = start; j <= i; j++) sum += nums[j];
    out.push(sum / (i - start + 1));
  }
  return out;
}

