function groupAnagrams(words) {
  const keyOf = (w) => w.toLowerCase().replace(/[^a-z]/g, '').split('').sort().join('');
  const order = [];
  const map = new Map();
  for (const w of words) {
    const k = keyOf(w);
    if (!map.has(k)) { map.set(k, []); order.push(k); }
    map.get(k).push(w);
  }
  return order.map((k) => map.get(k));
}

