reference:
function addBusinessDays(startDay, n, holidays) {
  const hol = new Set(holidays || []);
  const working = (d) => {
    const m = ((d % 7) + 7) % 7;
    return m !== 5 && m !== 6 && !hol.has(d);
  };
  let day = startDay;
  let left = n;
  while (left > 0) {
    day++;
    if (working(day)) left--;
  }
  return day;
}

