function parseKeyValues(s) {
  const out = {};
  for (const raw of String(s).split(';')) {
    if (raw.trim() === '') continue;
    const i = raw.indexOf('=');
    if (i === -1) return null;
    out[raw.slice(0, i).trim()] = raw.slice(i + 1).trim();
  }
  return out;
}

