function dedupeKeepLast(items, key) {
  const firstIndex = new Map();
  const last = new Map();
  const order = [];
  for (const it of items) {
    const k = it[key];
    if (!firstIndex.has(k)) { firstIndex.set(k, order.length); order.push(k); }
    last.set(k, it);
  }
  return order.map((k) => last.get(k));
}

