function bankersRound(x, k) {
  const f = Math.pow(10, k);
  const scaled = x * f;
  const low = Math.floor(scaled);
  const diff = scaled - low;
  let r;
  if (diff > 0.5) r = low + 1;
  else if (diff < 0.5) r = low;
  else r = low % 2 === 0 ? low : low + 1;
  return r / f;
}

