function truncateAtWord(s, n) {
  if (!(n >= 1)) return null;
  if (s.length <= n) return s;
  if (n < 3) return s.slice(0, n);
  const budget = n - 3;
  let cut = s.slice(0, budget);
  const sp = cut.lastIndexOf(' ');
  if (sp > 0) cut = cut.slice(0, sp);
  return cut.replace(/\s+$/, '') + '...';
}

