function compareSemver(a, b) {
  const RE = /^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?$/;
  const pa = RE.exec(a), pb = RE.exec(b);
  if (!pa || !pb) return null;
  for (let i = 1; i <= 3; i++) {
    const x = Number(pa[i]), y = Number(pb[i]);
    if (x !== y) return x < y ? -1 : 1;
  }
  const ta = pa[4], tb = pb[4];
  if (ta === undefined && tb === undefined) return 0;
  if (ta === undefined) return 1;
  if (tb === undefined) return -1;
  const xa = ta.split('.'), xb = tb.split('.');
  const len = Math.min(xa.length, xb.length);
  for (let i = 0; i < len; i++) {
    const u = xa[i], v = xb[i];
    const un = /^\d+$/.test(u), vn = /^\d+$/.test(v);
    if (un && vn) { if (Number(u) !== Number(v)) return Number(u) < Number(v) ? -1 : 1; }
    else if (un !== vn) return un ? -1 : 1;
    else if (u !== v) return u < v ? -1 : 1;
  }
  if (xa.length === xb.length) return 0;
  return xa.length < xb.length ? -1 : 1;
}

