function roundHalfEven(s, places) {
  const neg = s.startsWith('-');
  const t = neg ? s.slice(1) : s;
  const dot = t.indexOf('.');
  const int = dot === -1 ? t : t.slice(0, dot);
  const frac = dot === -1 ? '' : t.slice(dot + 1);
  const keep = frac.slice(0, places).padEnd(places, '0');
  const rest = frac.slice(places);
  let roundUp = false;
  if (rest.length > 0) {
    const first = rest[0];
    const tailZero = /^0*$/.test(rest.slice(1));
    if (first > '5' || (first === '5' && !tailZero)) roundUp = true;
    else if (first === '5' && tailZero) {
      const lastKept = places > 0 ? keep[places - 1] : (int[int.length - 1] || '0');
      roundUp = Number(lastKept) % 2 === 1;
    }
  }
  let digits = int + keep;
  if (roundUp) {
    const arr = digits.split('');
    let i = arr.length - 1;
    for (;;) {
      if (i < 0) { arr.unshift('1'); break; }
      if (arr[i] === '9') { arr[i] = '0'; i -= 1; }
      else { arr[i] = String(Number(arr[i]) + 1); break; }
    }
    digits = arr.join('');
  }
  let ip = places > 0 ? digits.slice(0, digits.length - places) : digits;
  const fp = places > 0 ? digits.slice(digits.length - places) : '';
  ip = ip.replace(/^0+(?=\d)/, '');
  if (ip === '') ip = '0';
  let out = places > 0 ? ip + '.' + fp : ip;
  const isZero = /^0(\.0*)?$/.test(out);
  if (neg && !isZero) out = '-' + out;
  return out;
}

