function jsonPointerGet(doc, ptr) {
  if (ptr === '') return { found: true, value: doc };
  if (!ptr.startsWith('/')) return { found: false, value: null };
  let cur = doc;
  for (const raw of ptr.slice(1).split('/')) {
    const key = raw.replace(/~1/g, '/').replace(/~0/g, '~');
    if (Array.isArray(cur)) {
      if (!/^(0|[1-9]\d*)$/.test(key)) return { found: false, value: null };
      const i = Number(key);
      if (i >= cur.length) return { found: false, value: null };
      cur = cur[i];
    } else if (cur !== null && typeof cur === 'object') {
      if (!Object.prototype.hasOwnProperty.call(cur, key)) return { found: false, value: null };
      cur = cur[key];
    } else {
      return { found: false, value: null };
    }
  }
  return { found: true, value: cur };
}

