function topoOrder(nodes, edges) {
  const adj = new Map();
  const indeg = new Map();
  for (const n of nodes) { adj.set(n, new Set()); indeg.set(n, 0); }
  for (const [u, v] of edges) {
    if (!adj.get(u).has(v)) { adj.get(u).add(v); indeg.set(v, indeg.get(v) + 1); }
  }
  const avail = nodes.filter((n) => indeg.get(n) === 0).sort();
  const order = [];
  while (avail.length > 0) {
    const n = avail.shift();
    order.push(n);
    for (const m of [...adj.get(n)].sort()) {
      indeg.set(m, indeg.get(m) - 1);
      if (indeg.get(m) === 0) { avail.push(m); avail.sort(); }
    }
  }
  if (order.length < nodes.length) {
    const placed = new Set(order);
    return { stuck: nodes.filter((n) => !placed.has(n)).sort() };
  }
  return { order };
}

