function makeCache(cap) {
  const store = new Map();
  let tick = 0;
  return {
    get(key) {
      const e = store.get(key);
      if (e === undefined) return null;
      e.freq += 1;
      tick += 1;
      e.last = tick;
      return e.value;
    },
    set(key, value) {
      if (cap <= 0) return;
      const e = store.get(key);
      tick += 1;
      if (e !== undefined) {
        e.value = value;
        e.freq += 1;
        e.last = tick;
        return;
      }
      if (store.size >= cap) {
        let vk = null;
        let ve = null;
        for (const [k, x] of store) {
          if (ve === null || x.freq < ve.freq || (x.freq === ve.freq && x.last < ve.last)) { vk = k; ve = x; }
        }
        store.delete(vk);
      }
      store.set(key, { value, freq: 1, last: tick });
    },
    keys() {
      return [...store.keys()].sort();
    },
  };
}

