function netIntervals(add, remove) {
  const norm = (list) => {
    const xs = list.filter(([s, e]) => e > s).map(([s, e]) => [s, e]).sort((a, b) => a[0] - b[0] || a[1] - b[1]);
    const out = [];
    for (const [s, e] of xs) {
      if (out.length > 0 && s <= out[out.length - 1][1]) {
        if (e > out[out.length - 1][1]) out[out.length - 1][1] = e;
      } else {
        out.push([s, e]);
      }
    }
    return out;
  };
  const A = norm(add);
  const R = norm(remove);
  const res = [];
  for (const iv of A) {
    let s = iv[0];
    const e = iv[1];
    for (const [rs, re] of R) {
      if (re <= s || rs >= e) continue;
      if (rs > s) res.push([s, rs]);
      if (re > s) s = re;
      if (s >= e) break;
    }
    if (s < e) res.push([s, e]);
  }
  return res;
}

