function coalesce(events, windowMs) {
  const out = [];
  let burst = null;
  for (const [t, id] of events) {
    if (burst !== null && t - burst.lastT < windowMs) {
      burst.lastT = t;
      if (!burst.ids.includes(id)) burst.ids.push(id);
    } else {
      if (burst !== null) out.push([burst.lastT, burst.ids]);
      burst = { lastT: t, ids: [id] };
    }
  }
  if (burst !== null) out.push([burst.lastT, burst.ids]);
  return out;
}

