function addDecimalStrings(a, b) {
  const parse = (x) => {
    const neg = x.startsWith('-');
    const t = neg ? x.slice(1) : x;
    const dot = t.indexOf('.');
    const i = dot === -1 ? t : t.slice(0, dot);
    const f = dot === -1 ? '' : t.slice(dot + 1);
    return { neg, i, f };
  };
  const A = parse(a);
  const B = parse(b);
  const fl = Math.max(A.f.length, B.f.length);
  const toBig = (p) => {
    const v = BigInt(p.i + p.f.padEnd(fl, '0'));
    return p.neg ? -v : v;
  };
  let sum = toBig(A) + toBig(B);
  const neg = sum < 0n;
  if (neg) sum = -sum;
  const s = sum.toString().padStart(fl + 1, '0');
  let ip = s.slice(0, s.length - fl).replace(/^0+(?=\d)/, '');
  const fp = fl > 0 ? s.slice(s.length - fl).replace(/0+$/, '') : '';
  let out = fp !== '' ? ip + '.' + fp : ip;
  if (neg && out !== '0') out = '-' + out;
  return out;
}

