function parseCsvRecord(line) {
  const fields = [];
  let i = 0;
  for (;;) {
    let field = '';
    if (line[i] === '"') {
      i += 1;
      for (;;) {
        if (i >= line.length) return null;
        if (line[i] === '"') {
          if (line[i + 1] === '"') { field += '"'; i += 2; }
          else { i += 1; break; }
        } else {
          field += line[i];
          i += 1;
        }
      }
      if (i < line.length && line[i] !== ',') return null;
    } else {
      while (i < line.length && line[i] !== ',') {
        field += line[i];
        i += 1;
      }
    }
    fields.push(field);
    if (i >= line.length) return fields;
    i += 1;
  }
}

